// Paket main - UI-Texte des Datei-Managers (MC-Modus) in allen Sprachen
//
// Die Texte werden beim Programmstart in extraTranslations (i18n_extra.go)
// eingemischt und gelten damit als normale Zusatztexte: Sie werden mit
// m.tr(key) abgerufen und von tests/i18n_complete_test.go auf
// Vollständigkeit geprüft. Eigene Datei, damit i18n_extra.go nicht
// unüberschaubar wird.
//
// Mit "|" getrennte Listen (Menü, F-Tasten, Spaltenköpfe) müssen in jeder
// Sprache genau so viele Teile haben wie im Englischen (Test
// TestFileManagerI18nLists). F-Tasten-Beschriftungen möglichst kurz halten
// (höchstens 7 Zeichen), sonst werden sie bei 80 Spalten gekürzt.
//
// @author Kurt Ingwer
// @date   2026-10-22 08:20
